custom_css:
/* 「QuietRoom.org 2.5」仿个人博客小站
   作者：王北方。仅在酒馆内使用，不可商用二传；二改自用请随意 (｡•ᴗ•｡)
   图来自 Pinterest 公开图和 Canva 素材，仅自用。
   致谢 Discord「旅程」美化教程帖与各位老师：
   · 墨千尾（@inkfoxxxx）老师的《拼好码》：占位字换成自己的字、正则和脚本列表留白
   · 景然（@rann_jing）老师的「思维链可滑动容器」 */

/*! 自定义：能改的都在「可以改的内容」 :root 里。文字只改引号里的，\A 是换行；图片换 url("...") 里的直链。 */

/*! 正文字体：第一行换成字体网站给的 CSS 链接；第二行只需把引号内的LXGW WenKai换成你的字体名称即可 */
@import url("https://fontsapi.zeoseven.com/292/main/result.css");
:root { --hp-font-body: "LXGW WenKai"; }

/*! 可以改的内容 */
:root {
  /*! 地址栏网址 */
  --hp-t-url: "quietroom.org/diary/october.html";
  /*! 横幅图（约 4:1） */
  --hp-banner: url("https://img.remit.ee/i/3caujKjBM4Yl");
  /*! 横幅中间的字图，不要就写 none */
  --hp-word: url("https://img.remit.ee/i/MZQbmbLOH5Ef");
  /*! 聊天区压在壁纸上的白，0% 最透 */
  --hp-veil: 22%;
  /*! 日志卡片等毛玻璃的不透明度，越小越透（模糊强度在酒馆「用户设置 → 模糊强度」里调） */
  --hp-glass-opacity: 62%;
  /*! 电脑左栏底图 */
  --hp-page: url("https://img.remit.ee/i/rK9rYXMSUj8p");
  /*! 左栏底图上的白，越大越淡 */
  --hp-wash: rgba(245, 245, 246, 0.5);
  /*! 头像（方，透明底） */
  --hp-profile: url("https://img.remit.ee/i/YMwpe8eEQqdU");
  /*! about me 标题 */
  --hp-t-about-title: "about me ✧";
  /*! 签名 */
  --hp-t-sign: "welcome to my little corner of the internet ˚₊‧";
  /*! about me 几行 */
  --hp-t-about: "name: guest ♡\A mood: sleepy (－ω－) zzz\A status: ● online";
  /*! about me 行数 */
  --hp-about-lines: 3;
  /*! 歌名 */
  --hp-t-song: "apocalypse";
  /*! 歌手 */
  --hp-t-artist: "cigarettes after sex";
  /*! 播放器时间行 */
  --hp-t-np-time: "1:12   ◄◄  ❚❚  ►►   4:50";
  /*! 封面（方） */
  --hp-cover: url("https://img.remit.ee/i/dFIpEuFfNeKl");
  /*! 留言板初始样子，「名字: 留言」一行一条 */
  --hp-t-guestbook: "mio: ur site is so pretty (˶ᵔ ᵕ ᵔ˶)\A anon: the clouds!! ⋆˙⟡\A yuki: hi hi ₍ᐢ. .ᐢ₎";
  /*! 页脚 */
  --hp-t-footer: "thank you for visiting ♡ (˶ᵔ ᵕ ᵔ˶)\A you are visitor no. 000042 · come back soon ⋆˙⟡";
  /*! 左栏最底下那行（配套脚本）：{since} 开始那天 {days} 第几天 */
  --hp-t-stats: "since {since} · day {days}";
  /*! 留言框占位字 */
  --hp-t-placeholder: "say hi to the webmaster ₍ᐢ. .ᐢ₎";
  /*! 登录页副标题 */
  --hp-t-gate-sub: "a little diary on the internet ˚₊‧";
  /*! 顶栏九个标签：AI 配置、API、格式、世界书、用户设置、背景、扩展、人设、角色 */
  --hp-tab-1: "ai";
  --hp-tab-2: "connect";
  --hp-tab-3: "format";
  --hp-tab-4: "lore";
  --hp-tab-5: "settings";
  --hp-tab-6: "walls";
  --hp-tab-7: "extras";
  --hp-tab-8: "about me";
  --hp-tab-9: "friends";
  /*! 手机上的标签缩写 */
  --hp-tabm-1: "ai";
  --hp-tabm-2: "api";
  --hp-tabm-3: "fmt";
  --hp-tabm-4: "lore";
  --hp-tabm-5: "ui";
  --hp-tabm-6: "bg";
  --hp-tabm-7: "ext";
  --hp-tabm-8: "me";
  --hp-tabm-9: "pals";
}

@font-face { font-family: "DotGothic16"; font-style: normal; font-weight: 400; font-display: swap; src: url(https://gstatic.loli.net/s/dotgothic16/v22/v6-QGYjBJFKgyw5nSoDAGH7M6X96P0rS.woff2) format("woff2"); }
@font-face { font-family: "IBM Plex Mono"; font-style: normal; font-weight: 400; font-display: swap; src: url(https://gstatic.loli.net/s/ibmplexmono/v20/-F63fjptAgt5VM-kVkqdyU8n1i8q131nj-o.woff2) format("woff2"); }
@font-face { font-family: "IBM Plex Mono"; font-style: normal; font-weight: 500; font-display: swap; src: url(https://gstatic.loli.net/s/ibmplexmono/v20/-F6qfjptAgt5VM-kVkqdyU8n3twJwlBFgsAXHNk.woff2) format("woff2"); }
@font-face { font-family: "IBM Plex Mono"; font-style: italic; font-weight: 400; font-display: swap; src: url(https://gstatic.loli.net/s/ibmplexmono/v20/-F6pfjptAgt5VM-kVkqdyU8n1ioa1XdgregdFA.woff2) format("woff2"); }
@font-face { font-family: "Cormorant Garamond"; font-style: italic; font-weight: 500; font-display: swap; src: url(https://gstatic.loli.net/s/cormorantgaramond/v21/co3smX5slCNuHLi8bLeY9MK7whWMhyjYrGFEsdtdc62E6zd5wDD-iNM8A_6pUKz9.woff2) format("woff2"); }

