:root.hp-night {
  --hp-paper: #1D1E22;
  --hp-box: #25262B;
  --hp-field: #2C2D33;
  --hp-tint: #23262E;
  --hp-tab: #2A2B31;
  --hp-note: #222328;
  --hp-ink: #E3E4E8;
  --hp-ink2: #A4A7B0;
  --hp-ink3: #6F727B;
  --hp-quote: #A9B9D8;
  --hp-line: #3A3C44;
  --hp-frame: #4B4D56;
  --hp-frame-soft: #2E3036;
  --hp-btn: #C8CAD2;
  --hp-btn-hover: #E3E4E8;
  --hp-btn-ink: #1D1E22;
  --hp-wash: rgba(29, 30, 34, 0.55);
  --hp-veil: 66%;
  --hp-load-wall: #18191C;
  --hp-hi: rgba(255, 255, 255, 0.10);
  --hp-hi-soft: rgba(255, 255, 255, 0.05);
  --hp-drop: rgba(0, 0, 0, 0.6);
  --hp-mist: rgba(20, 21, 26, 0.45);
  --hp-banner-rim: rgba(255, 255, 255, 0.06);
  --hp-banner: url("https://img.remit.ee/i/ixbidAmdxxhJ");
  --hp-page: url("https://img.remit.ee/i/ZjJXJFeisErg");
  --hp-word: url("https://img.remit.ee/i/m6NBNfIRrGv9");
  --hp-profile: url("https://img.remit.ee/i/EXtXPR0M9EX6");
  --hp-welcome: url("https://img.remit.ee/i/HlwM45kLTH14");
  --SmartThemeBodyColor: #E3E4E8 !important;
  --SmartThemeEmColor: #A4A7B0 !important;
  --SmartThemeUnderlineColor: #E3E4E8 !important;
  --SmartThemeQuoteColor: #A9B9D8 !important;
  --SmartThemeBlurTintColor: #25262B !important;
  --SmartThemeBorderColor: #3A3C44 !important;
  --SmartThemeShadowColor: rgba(0, 0, 0, 0) !important;
  color-scheme: dark;
}

:root {
  --hp-font-label: var(--hp-latin-label), var(--hp-font-cjk);            --hp-font-mono: var(--hp-latin-mono), "Menlo", "Consolas", var(--hp-font-cjk);     --hp-font-site: var(--hp-latin-site), "Georgia", var(--hp-font-cjk);    --mainFontFamily: var(--hp-font-cjk);
  --hp-fs-small: calc(var(--mainFontSize) * 0.74);
  --hp-fs-micro: calc(var(--mainFontSize) * 0.68);
  --hp-pad: 14px;                --hp-pad-b: 5px;               --hp-gap: 20px;                --hp-side: 204px;              --hp-av: 46px;                 --hp-radius: 10px;             --hp-box-radius: 10px;         --hp-banner-h: 156px;
  --hp-head-top: 12px;             --hp-dash: repeating-linear-gradient(90deg, var(--hp-line) 0 3px, transparent 3px 6px);
    --topBarBlockSize: calc(var(--mainFontSize) * 4.9);
  --hp-tabs-h: calc(var(--mainFontSize) * 2.5);
    --hp-glass: color-mix(in srgb, var(--hp-box) var(--hp-glass-opacity), transparent);
  --hp-glass-tint: color-mix(in srgb, var(--hp-tint) var(--hp-glass-opacity), transparent);
  --hp-glass-blur: blur(calc(var(--blurStrength, 12) * 1px)) saturate(1.15);
  --hp-box-shadow: inset 0 1px 0 var(--hp-hi), inset 0 0 0 1px var(--hp-hi-soft), 0 6px 18px -12px var(--hp-drop);
  --hp-win-shadow: 0 2px 0 var(--hp-frame-soft), 0 18px 36px -18px rgba(40, 42, 50, 0.4);
    --hp-gloss: linear-gradient(180deg, var(--hp-hi), transparent 55%), linear-gradient(var(--hp-tab), var(--hp-tab));
}

/* ---------- 顶栏 ---------- */

#top-bar {
  height: var(--topBarBlockSize);
  border: 1.5px solid var(--hp-frame);
  border-bottom: 0;
  border-radius: var(--hp-radius) var(--hp-radius) 0 0;
  background-image: linear-gradient(180deg, var(--hp-hi), var(--hp-paper) 46%), linear-gradient(var(--hp-paper), var(--hp-paper));   box-shadow: inset 0 1px 0 var(--hp-hi);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

#top-settings-holder {
  height: var(--hp-tabs-h);
  align-items: flex-end;
  justify-content: flex-start;
  gap: 5px;
  padding: 7px 10px 0;
  box-sizing: border-box;
}

#top-bar::before {
  content: var(--hp-t-favicon) "\2002" var(--hp-t-url);
  position: absolute;
  left: 10px;
  right: calc(var(--mainFontSize) * 5.4);
  top: var(--hp-tabs-h);
  height: calc(var(--topBarBlockSize) - var(--hp-tabs-h));
  box-sizing: border-box;
  margin: 5px 0 0;
  padding: 0 12px;
  display: flex;
  align-items: center;
  border: 1px solid var(--hp-line);
  border-radius: 999px;
  background: var(--hp-box);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-mono);
  letter-spacing: 0.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--hp-ink);
  pointer-events: none;
}

#top-bar::after {
  content: var(--hp-t-reload);
  position: absolute;
  right: 10px;
  top: var(--hp-tabs-h);
  height: calc(var(--topBarBlockSize) - var(--hp-tabs-h));
  width: calc(var(--mainFontSize) * 4.8);
  box-sizing: border-box;
  margin: 5px 0 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--hp-line);
  border-radius: 999px;
  background: var(--hp-box);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-mono);
  color: var(--hp-ink2);
  pointer-events: none;
}

#top-settings-holder::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: var(--hp-tabs-h);
  border-top: 1px solid var(--hp-line);
  pointer-events: none;
}

body #top-settings-holder > .drawer,
body #top-settings-holder > .drawer > .drawer-toggle {
  width: auto;
  flex: none;
}

body #top-settings-holder .drawer-icon,
body #top-settings-holder > :not(.drawer)[class*="fa-"],
body #top-settings-holder .drawer-toggle > [class*="fa-"]:not(.drawer-icon) {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.45em;
  width: auto;   min-width: 0;
  height: calc(var(--hp-tabs-h) - 7px);
  box-sizing: border-box;
  margin: 0;
  padding: 0 0.75em;
  white-space: nowrap;
  border: 1px solid var(--hp-line);
  border-bottom: 0;
  border-radius: 7px 7px 0 0;
  background: var(--hp-gloss);
  box-shadow: inset 0 1px 0 var(--hp-hi);
  color: var(--hp-ink2);
  font-size: var(--hp-fs-small);
  line-height: 1;
  opacity: 1;
  text-shadow: none;
  filter: none;
  transition: none;
}

body #top-settings-holder .drawer-icon:hover,
body #top-settings-holder > :not(.drawer)[class*="fa-"]:hover {
  color: var(--hp-ink);
  background: var(--hp-box);
}

body #top-settings-holder .drawer-icon.openIcon {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0) 60%), var(--hp-btn);
  border-color: var(--hp-btn);
  box-shadow: none;
  color: var(--hp-btn-ink);
}

body #top-settings-holder .drawer-toggle > .fa-regular,
body #top-settings-holder > .fa-regular {
  font-weight: 900;
}

body #top-settings-holder .drawer-toggle :is(img, svg),
body #top-settings-holder > :is(img, svg) {
  width: auto;
  height: calc(var(--mainFontSize) * 1.1);
  filter: grayscale(1) contrast(1.1);
}

body #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button,
  #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon::before {
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-label);
  letter-spacing: 0.04em;
}

body #top-settings-holder > #ai-config-button .drawer-icon::before { content: var(--hp-tab-1); }
body #top-settings-holder > #sys-settings-button .drawer-icon::before { content: var(--hp-tab-2); }
body #top-settings-holder > #advanced-formatting-button .drawer-icon::before { content: var(--hp-tab-3); }
body #top-settings-holder > #WI-SP-button .drawer-icon::before { content: var(--hp-tab-4); }
body #top-settings-holder > #user-settings-button .drawer-icon::before { content: var(--hp-tab-5); }
body #top-settings-holder > #backgrounds-button .drawer-icon::before { content: var(--hp-tab-6); }
body #top-settings-holder > #extensions-settings-button .drawer-icon::before { content: var(--hp-tab-7); }
body #top-settings-holder > #persona-management-button .drawer-icon::before { content: var(--hp-tab-8); }
body #top-settings-holder > #rightNavHolder .drawer-icon::before { content: var(--hp-tab-9); }

body #top-settings-holder > .drawer:not(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button,
  #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon[title]:not([title=""])::before,
body #top-settings-holder > :not(.drawer)[class*="fa-"][title]:not([title=""])::before {
  content: attr(title);
  display: block;
  max-width: 7em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-label);
  letter-spacing: 0.04em;
}

body #top-settings-holder > .drawer:not(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button,
  #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) .drawer-icon[title]:not([title=""])[data-hp-tab]::before,
body #top-settings-holder > :not(.drawer)[class*="fa-"][title]:not([title=""])[data-hp-tab]::before {
  content: attr(data-hp-tab);
}

body #top-settings-holder .drawer-icon.fa-plug-circle-exclamation::before {
  opacity: 0.45;
}

/* ---------- 聊天区 ---------- */

#sheld {
  --hp-veil-c: color-mix(in srgb, var(--hp-paper) var(--hp-veil), transparent);
  background: linear-gradient(var(--hp-veil-c), var(--hp-veil-c));
  border: 1.5px solid var(--hp-frame);
  border-top: 0;
  border-radius: 0 0 var(--hp-radius) var(--hp-radius);
  box-shadow: var(--hp-win-shadow);
}

#chat {
  overflow-x: hidden;     gap: var(--hp-gap);
  padding: var(--hp-pad) var(--hp-pad) 0;
  border: 0;
  background: none;
  color: var(--hp-ink);
  text-shadow: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  scrollbar-width: thin;
  scrollbar-color: var(--hp-line) transparent;
}

#sheld > #extensionTopBar,
#sheld > #extensionConnectionProfiles {
  width: auto;
  margin: 0;
  border: 0;
  border-bottom: 1px solid var(--hp-line);
  border-radius: 0;
  background: var(--hp-paper);
  box-shadow: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  color: var(--hp-ink2);
  font-family: var(--hp-font-mono);
}

#sheld > #extensionTopBar {
  flex-wrap: nowrap;
  align-items: center;
}

#sheld > #extensionTopBar > :is(#extensionTopBarChatName, #extensionTopBarSearchInput) {
  min-width: 0;
  font-family: var(--hp-font-mono);
}

@media screen and (max-width: 1000px) {
  #sheld > #extensionTopBar > #extensionTopBarSearchInput {
    flex: 0 1 5.5em;
  }
}

@media screen and (min-width: 1001px) {
  #movingDivs > #extensionSideBar {
    top: calc(var(--topBarBlockSize) + var(--hp-pad));
    bottom: auto;
    left: calc((100vw - var(--sheldWidth)) / 2 + var(--hp-pad));
    width: var(--hp-side);
    height: calc(100vh - var(--topBarBlockSize) - var(--hp-pad) * 2);
    height: calc(100dvh - var(--topBarBlockSize) - var(--hp-pad) * 2);
    max-width: none;
    max-height: none;
  }
}

#movingDivs > #extensionSideBar {
  border: 1px solid var(--hp-frame-soft);
  border-radius: var(--hp-box-radius);
  background: var(--hp-box);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  filter: none;
  box-shadow: var(--hp-win-shadow);
  color: var(--hp-ink);
  font-family: var(--hp-font-mono);
}

#chat::before {
  content: "";
  order: -2;
  align-self: stretch;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  height: var(--hp-banner-h);
  margin: 0;
  padding: 0;
  border: 1px solid var(--hp-line);
  border-radius: var(--hp-box-radius);
  background:
    var(--hp-sparkle) 16px 14px / auto 34px no-repeat,
    var(--hp-word) center 50% / auto 68% no-repeat,
    radial-gradient(ellipse 36% 38% at 50% 50%, var(--hp-mist), transparent 100%),
    var(--hp-banner) center / cover no-repeat,
    var(--hp-tint);
  box-shadow: inset 0 0 0 4px var(--hp-banner-rim), var(--hp-box-shadow);
  font: italic 500 calc(var(--mainFontSize) * 2.6) / 1 var(--hp-font-site);
  letter-spacing: 0.02em;
  white-space: nowrap;
  color: var(--hp-ink);
  text-shadow: none;
}

#chat::after {
  content: var(--hp-t-footer);
  order: 999;
  align-self: center;
  flex: none;
  box-sizing: border-box;
  max-width: 100%;
  margin: 2px 0 var(--hp-pad);
  padding: 8px 18px;
  border: 1px solid var(--hp-line);
  border-radius: var(--hp-box-radius);
  background: var(--hp-glass);
  box-shadow: var(--hp-box-shadow);
  -webkit-backdrop-filter: var(--hp-glass-blur);
  backdrop-filter: var(--hp-glass-blur);
  font: 400 var(--hp-fs-micro) / 1.8 var(--hp-font-mono);
  letter-spacing: 0.04em;
  text-align: center;
  white-space: pre-wrap;
  color: var(--hp-ink2);
}

#chat[data-tt-chat-surface="bounded"] {
  position: relative;
  padding-top: calc(var(--hp-pad) + var(--hp-banner-h) + var(--hp-gap));
}

#chat[data-tt-chat-surface="bounded"]::before {
  position: absolute;
  top: var(--hp-pad);
  left: var(--hp-pad);
  right: var(--hp-pad);
}

body {
  background-color: transparent;
}

#form_sheld {
  margin-top: 0;
  padding: 10px var(--hp-pad) var(--hp-pad-b);
}

#show_more_messages {
  order: -1;
  align-self: stretch;
  margin: 0;
  padding: 0.5em 0;
  border: 1px dashed var(--hp-line);
  border-radius: var(--hp-box-radius);
  background: var(--hp-glass);
  color: var(--hp-ink2);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-mono);
  text-align: center;
}

/* ---------- 左栏（没装脚本时） ---------- */

@media screen and (min-width: 1001px) {
  #chat,
  #show_more_messages {
    margin-left: calc(var(--hp-side) + var(--hp-pad));
  }

  #sheld > #extensionTopBar,
  #sheld > #extensionConnectionProfiles {
    margin-left: calc(var(--hp-side) + var(--hp-pad) * 1.5 + 1px);     }

  #form_sheld {
    width: auto;
    margin: 1px 0 0 calc(var(--hp-side) + var(--hp-pad));   }

    #sheld {
    --hp-strip: calc(var(--hp-side) + var(--hp-pad) * 1.5);
    background:
      linear-gradient(var(--hp-line), var(--hp-line)) var(--hp-strip) 0 / 1px 100% no-repeat,
      linear-gradient(var(--hp-wash), var(--hp-wash)) 0 0 / var(--hp-strip) 100% no-repeat,
      var(--hp-page) 0 0 / var(--hp-strip) 100% no-repeat,
      linear-gradient(var(--hp-paper), var(--hp-paper)) 0 0 / var(--hp-strip) 100% no-repeat,
      linear-gradient(var(--hp-veil-c), var(--hp-veil-c));
  }

  #sheld::before,
  #sheld::after,
  #form_sheld::after {
    position: absolute;
    z-index: 2;
    left: var(--hp-pad);
    width: var(--hp-side);
    box-sizing: border-box;
    padding: 10px 14px 12px;
    border: 1px solid var(--hp-line);
    border-radius: var(--hp-box-radius);
    box-shadow: var(--hp-box-shadow);
    font: 400 var(--hp-fs-small) / 1.8 var(--hp-font-mono);
    white-space: pre-wrap;
    overflow: hidden;
    color: var(--hp-ink2);
    pointer-events: none;
    -webkit-backdrop-filter: var(--hp-glass-blur);
    backdrop-filter: var(--hp-glass-blur);
  }

    #sheld::before {
    content: var(--hp-t-about-title) "\A\A\A\A\A\A\A\A\A" var(--hp-t-about);
    top: var(--hp-pad);
    background:
      var(--hp-itsme) right 6px top calc(10px + 2.4em) / 6.4em auto no-repeat,
      var(--hp-profile) center top calc(10px + 2.3em) / auto 13em no-repeat,
      var(--hp-dash) 14px calc(10px + 1.8em) / calc(100% - 28px) 1px no-repeat,
      var(--hp-glass);
  }

    #sheld::after {
    content: var(--hp-t-np-title) "\A\A" var(--hp-t-song) "\A" var(--hp-t-artist) "\A\A" var(--hp-t-np-time);
    top: calc(var(--hp-pad) * 2 + 22px + (9 + var(--hp-about-lines)) * 1.8 * var(--hp-fs-small) + 2px);
    white-space: pre;       background:
      var(--hp-bow) right -4px top -6px / 32px auto no-repeat,
      var(--hp-cover) right 12px top calc(10px + 3.8em) / 3.2em 3.2em no-repeat,
      linear-gradient(var(--hp-tab), var(--hp-tab)) calc(14px + 38% - 3px) calc(10px + 8.1em - 5px) / 6px 12px no-repeat,
      linear-gradient(var(--hp-frame), var(--hp-frame)) calc(14px + 38% - 4px) calc(10px + 8.1em - 6px) / 8px 14px no-repeat,
      linear-gradient(var(--hp-btn), var(--hp-btn)) 14px calc(10px + 8.1em) / 38% 2px no-repeat,
      linear-gradient(var(--hp-line), var(--hp-line)) 14px calc(10px + 8.1em) / calc(100% - 28px) 2px no-repeat,
      var(--hp-dash) 14px calc(10px + 1.8em) / calc(100% - 28px) 1px no-repeat,
      var(--hp-glass);
  }

    #form_sheld::after {
    content: var(--hp-t-gb-title) "\A\A" var(--hp-t-guestbook);
    bottom: var(--hp-pad-b);
    background:
      var(--hp-dash) 14px calc(10px + 1.8em) / calc(100% - 28px) 1px no-repeat,
      var(--hp-glass);
  }

  @media (max-height: 780px) {
    #form_sheld::after {
      content: none;
    }
  }

    body.hp-js #sheld::before,
  body.hp-js #sheld::after,
  body.hp-js #form_sheld::after {
    content: none;
  }
}

