}

#chat .mes:not(.smallSysMes) .tokenCounterDisplay::before {
  content: var(--hp-t-tokens) "\2002";
  color: var(--hp-ink3);
}

#chat .mes:not(.smallSysMes) .mes_timer::before {
  content: var(--hp-t-timer) "\2002";
}

#chat .mes:not(.smallSysMes) .tokenCounterDisplay:empty::before,
#chat .mes:not(.smallSysMes) .mes_timer:empty::before {
  content: none;
}

body[data-generating="true"] #chat .mes.last_mes:not(.smallSysMes) .mes_timer:empty {
  display: block;
}

#chat .mes:not(.smallSysMes) > .swipeRightBlock {
