  min-width: 0;
  height: auto;
  margin: 0;
  padding: 0;
  font: inherit;
  letter-spacing: inherit;
  color: var(--hp-ink2);
  opacity: 1;
}

#chat .mes .swipes-counter::before {
  content: "\00b7\2002";
  color: var(--hp-ink3);
}

#chat .mes .swipes-counter::after {
  content: "\2002\00b7";
  color: var(--hp-ink3);
}

#chat .mes .swipe_right {
  position: static;
}

#chat .mes .swipe_right,
#chat .mes > .swipe_left {
