}

#chat .mes .swipe_right::before { content: var(--hp-t-next); }
#chat .mes > .swipe_left::before { content: var(--hp-t-prev); }

#chat .mes:not(.smallSysMes) {
  --hp-swipe-w: 10em;
}

#chat .mes:not(.smallSysMes) > .swipeRightBlock {
  min-width: var(--hp-swipe-w);
  justify-content: flex-end;
}

body:not(.swipeAllMessages) #chat .mes:not(.last_mes) :is(.swipe_left, .swipe_right, .swipes-counter),
#chat .mes:not(.swipes_visible) .swipe_left,
#chat .mes:not(.swipes_visible, .last_swipe) .swipe_right,
