}

/* ---------- 输入栏 ---------- */

#form_sheld::before {
  content: none;
  display: block;
  box-sizing: border-box;
  width: fit-content;
  max-width: 100%;
  margin: 0 0 6px;
  padding: 2px 10px;
  border: 1px solid var(--hp-line);
  border-radius: 999px;
  background: var(--hp-glass);
  -webkit-backdrop-filter: var(--hp-glass-blur);
  backdrop-filter: var(--hp-glass-blur);
  font: 400 var(--hp-fs-micro) / 1.4 var(--hp-font-mono);
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--hp-ink2);
}

:root.hp-night #form_sheld::before {
  color: var(--hp-ink2);
}

body[data-generating="true"] #form_sheld::before {
  content: var(--hp-t-typing);
  color: var(--hp-ink2);
}

#send_form {
  --bottomFormIconSize: calc(var(--mainFontSize) * 1.15);
  margin: 0;
  padding: 6px 8px;
  border: 1px solid var(--hp-line);
  border-radius: var(--hp-box-radius);
  background-image: linear-gradient(var(--hp-glass), var(--hp-glass));   box-shadow: var(--hp-box-shadow);
  -webkit-backdrop-filter: var(--hp-glass-blur);
  backdrop-filter: var(--hp-glass-blur);
  color: var(--hp-ink);
}

#send_form:has(#send_textarea:focus-visible) {
  border-color: var(--hp-ink3);
}

#send_textarea {
  margin: 0;
  padding: 0.45em 0.8em;
  border: 1px solid var(--hp-line);
  border-radius: 6px;
  background: var(--hp-field);
  box-shadow: none;
  color: var(--hp-ink);
  font-family: var(--hp-font-cjk);
  text-shadow: none;
}

#send_textarea {
  clip-path: none;
}

#form_sheld:is(.script_success, .script_error, .script_aborted) #send_textarea {
  border-top-color: var(--hp-line);
}

#form_sheld.isExecutingCommandsFromChatInput.script_paused #send_textarea {
  animation: none;
}

#send_textarea:focus {
  border-color: var(--hp-ink3);
  outline: none;
}

#send_textarea::placeholder {
  color: transparent !important; }

/*! 占位字换成自己的字：墨千尾（@inkfoxxxx）老师《拼好码》 */
#nonQRFormItems {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 6px;
}

#nonQRFormItems > #leftSendForm { grid-column: 1; grid-row: 1; }
#nonQRFormItems > #send_textarea { grid-column: 2; grid-row: 1; }
#nonQRFormItems > #rightSendForm { grid-column: 3; grid-row: 1; }

#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
  content: var(--hp-t-placeholder);
  grid-column: 2;
  grid-row: 1;
  justify-self: start;
  align-self: center;
  max-width: calc(100% - 1.6em);
  margin-left: 0.8em;
  overflow: hidden;
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-mono);
  letter-spacing: 0.02em;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--hp-ink3);
  pointer-events: none;
}

#send_form.no-connection #nonQRFormItems:has(#send_textarea)::after {
  content: none;
}

#send_form.no-connection #send_textarea::placeholder {
  color: var(--hp-ink3) !important;   font: 400 var(--hp-fs-small) / 1.6 var(--hp-font-mono);
  text-align: left;
}

body.hp-js #nonQRFormItems:has(#send_textarea)::after {
  content: none;
}

body.hp-js #send_form #send_textarea::placeholder {
  color: var(--hp-ink3) !important;   font: 400 var(--hp-fs-small) / 1.6 var(--hp-font-mono);
  letter-spacing: 0.02em;
  text-align: left;     opacity: 1;
}

#leftSendForm,
#rightSendForm {
  gap: 4px;
  align-items: center;
}

#send_form :is(#leftSendForm, #rightSendForm) > :not(#send_but, #mes_stop, .stscript_btn) {
  display: grid;
  place-items: center;
  width: calc(var(--mainFontSize) * 2.1);
  height: calc(var(--mainFontSize) * 2.1);
  margin: 0;
  padding: 0;
  border: 1px solid var(--hp-line);
  border-radius: 50%;
  background: var(--hp-paper);
  box-shadow: none;
  color: var(--hp-ink2) !important;   font-size: calc(var(--mainFontSize) * 0.85) !important;   text-shadow: none;
  opacity: 1;
}

#send_form :is(#leftSendForm, #rightSendForm) > :not(#send_but, #mes_stop, .stscript_btn):hover {
  color: var(--hp-ink) !important;
  border-color: var(--hp-ink3);
}

#send_form #leftSendForm > #quickPersona {
  position: relative;
  display: block;
  padding: 2px;
  box-sizing: border-box;
}

#quickPersona > #quickPersonaImg {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: 50%;
  outline: 0;
  box-shadow: none;
