}

#quickPersona > #quickPersonaCaret {
  top: -3px;
  right: -4px;
  width: auto;
  height: auto;
  font-size: calc(var(--mainFontSize) * 0.55);
  color: var(--hp-ink3);
  text-shadow: none;
}

#quickPersonaMenu {
  border: 1px solid var(--hp-line);
  border-radius: var(--hp-box-radius);
  background: var(--hp-box);
  box-shadow: 0 14px 28px -12px rgba(0, 0, 0, 0.35);
}

#quickPersonaMenu ul.list-group {
  border: 0;
  background: none;
  box-shadow: none;
}

#quickPersonaMenu li.list-group-item {
  border: 0;
