/* ---------- 加载页 ---------- */

#preloader {
  background: var(--hp-load-wall);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

#loader,
#loader.splash-screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  transition: opacity var(--animation-duration-2x, 0.25s) ease-out, filter var(--animation-duration-2x, 0.25s) ease-out;
}

#loader .splash-logo,
#loader .splash-message {
  display: none;
}

#load-spinner,
#loader.splash-screen #load-spinner {
  position: relative;
  top: auto;
  left: auto;
  display: block;
  flex: none;
  width: min(calc(var(--mainFontSize) * 16), 70vw);
  height: calc(var(--mainFontSize) * 0.9);
  box-sizing: border-box;
  border: 1px solid var(--hp-ink3);
  border-radius: 999px;
  padding: 2px;
  background: var(--hp-field);
  color: var(--hp-ink);
  font: 400 var(--mainFontSize) / 1 var(--hp-font-label);   animation: none; }

#load-spinner::before {
  content: "";
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: 2px;
  width: calc((100% - 4px) * 0.28);
  border-radius: 999px;
  background: var(--hp-btn);
  animation: hp-progress 1.6s ease-in-out infinite alternate;
}

@keyframes hp-progress {
  from { transform: translateX(0); }
  to { transform: translateX(calc(100% / 0.28 - 100%)); }
}

#loader::before {
  content: var(--hp-t-loading);
  margin-bottom: calc(var(--mainFontSize) * 0.9);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hp-ink2);
}

#loader::after {
  content: var(--hp-t-loading-2);
  margin-top: calc(var(--mainFontSize) * 0.9);
  font: 400 var(--hp-fs-micro) / 1 var(--hp-font-mono);
  letter-spacing: 0.04em;
  color: var(--hp-ink3);
}

@media (prefers-reduced-motion: reduce) {
  #load-spinner::before {
    animation: none;
    width: 60%;
  }
}

