  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: color-mix(in srgb, var(--hp-paper) 55%, rgba(30, 32, 40, 0.55));
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  outline: none;
}

#hp-lightbox figure {
  max-width: min(78vw, 900px);
  margin: 0;
  padding: 8px 8px 6px;
  border: 1px solid var(--hp-line);
  border-radius: 4px;
  background: var(--hp-field);
  box-shadow: 0 24px 48px -20px rgba(0, 0, 0, 0.5);
}

#hp-lightbox img {
  display: block;
  width: min(70vw, 620px);
  height: min(68vh, 620px);
  height: min(68dvh, 620px);
  margin: 0 auto;
  object-fit: contain;
}

#hp-lightbox figcaption {
  padding: 6px 2px 0;
  text-align: center;
  color: var(--hp-ink2);
  font: 400 var(--hp-fs-micro) / 1.4 var(--hp-font-mono);
  letter-spacing: 0.04em;
}

#hp-lightbox button {
  margin: 0;
  border: 1px solid var(--hp-line);
  border-radius: 999px;
  background: var(--hp-box);
  color: var(--hp-ink2);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-mono);
  cursor: pointer;
}

#hp-lightbox .hp-lb-nav {
  flex: none;
  width: 32px;
  height: 32px;
}

#hp-lightbox .hp-lb-nav:disabled {
  opacity: 0.3;
  cursor: default;
}

#hp-lightbox .hp-lb-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
}

#hp-lightbox .hp-lb-del {
  position: absolute;
  bottom: 18px;
  left: 50%;
  padding: 4px 12px;
  transform: translateX(-50%);
  font-size: var(--hp-fs-micro);
}

@media screen and (max-width: 1000px) {
  #hp-lightbox {
    gap: 4px;
  }

  #hp-lightbox figure {
    max-width: calc(100vw - 84px);
  }

  #hp-lightbox img {
    width: calc(100vw - 104px);
    height: min(62vh, 520px);
    height: min(62dvh, 520px);
  }

  #hp-lightbox .hp-lb-nav {
    width: 28px;
    height: 28px;
  }
}

#hp-side .hp-stats {
  flex: none;
  margin: -2px 0 4px;
  white-space: pre-line;
  text-align: center;
  color: var(--hp-ink3);
  font: 400 var(--hp-fs-micro) / 1.7 var(--hp-font-mono);
  letter-spacing: 0.04em;
}

#hp-side .hp-sign {
  margin: 2px 0 6px;
  text-align: center;
  color: var(--hp-ink3);
  font-size: var(--hp-fs-micro);
}

#hp-scrim {
  display: none;
}

@media screen and (max-width: 1000px) {
  #hp-addr .hp-nav,
  #hp-addr .hp-reload {
    display: none;
  }

  #hp-addr {
    left: 6px;
    right: 6px;
    gap: 5px;
  }

  #hp-addr .hp-side-btn {
    display: grid;
    padding: 0 0.75em;
    border-color: var(--hp-btn);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.3), rgba(255, 255, 255, 0) 55%), var(--hp-btn);
    color: var(--hp-btn-ink);
  }

    #hp-side {
    position: fixed;
    z-index: 3002;
    top: var(--topBarBlockSize);
    bottom: auto;
    left: 0;
    height: calc(100vh - var(--topBarBlockSize));
    height: calc(100dvh - var(--topBarBlockSize));
    width: min(270px, 80vw);
    padding: 14px 12px;
    gap: 14px;
    border-right: 1px solid var(--hp-line);
    background:
      linear-gradient(color-mix(in srgb, var(--hp-paper) 88%, transparent), color-mix(in srgb, var(--hp-paper) 88%, transparent)),
      var(--hp-page) center / cover no-repeat,
      var(--hp-paper);
    box-shadow: 10px 0 30px -18px rgba(40, 42, 50, 0.6);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
    transform: translateX(-104%);
    transition: transform 0.28s ease;
  }

  body.hp-side-open #hp-side {
    transform: none;
  }

  #hp-scrim {
    display: block;
    position: fixed;
    z-index: 3001;
    top: var(--topBarBlockSize);
    left: 0;
    width: 100vw;
    height: calc(100vh - var(--topBarBlockSize));
    height: calc(100dvh - var(--topBarBlockSize));
    background: rgba(40, 42, 50, 0.22);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.28s;
  }

  body.hp-side-open #hp-scrim {
    opacity: 1;
    pointer-events: auto;
  }
}

#hp-gate {
  position: fixed;
  z-index: 100000;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  display: grid;
  place-items: center;
  background:
    linear-gradient(var(--hp-wash), var(--hp-wash)),
    var(--hp-page) center / cover no-repeat,
    var(--hp-paper);
  transition: opacity 0.5s ease;
}

#hp-gate.is-leaving {
  opacity: 0;
  pointer-events: none;
}

#hp-gate .hp-gate-win {
  position: relative;
  width: min(400px, calc(100vw - 32px));
  border: 1.5px solid var(--hp-frame);
  border-radius: 12px;
  background: var(--hp-paper);
  box-shadow: var(--hp-win-shadow), 0 30px 60px -30px rgba(40, 42, 50, 0.5);
  overflow: hidden;
  color: var(--hp-ink);
  font: 400 var(--hp-fs-small) / 1.6 var(--hp-font-mono);
}

#hp-gate .hp-gate-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border-bottom: 1px solid var(--hp-line);
  background: linear-gradient(180deg, var(--hp-hi), var(--hp-tab));
  color: var(--hp-ink2);
  font-size: var(--hp-fs-micro);
}

#hp-gate .hp-gate-bar i {
  width: 9px;
  height: 9px;
  border: 1px solid var(--hp-ink3);
  border-radius: 50%;
  background: linear-gradient(180deg, var(--hp-hi), var(--hp-line));
}

#hp-gate .hp-gate-bar span {
  flex: 1;
  text-align: center;
  margin-right: 33px;
}

#hp-gate .hp-gate-banner {
  position: relative;
  height: 108px;
  border-bottom: 1px solid var(--hp-line);
  background:
    var(--hp-welcome) center 40% / auto 46px no-repeat,
    radial-gradient(ellipse 42% 34% at 50% 40%, var(--hp-mist), transparent 100%),
    var(--hp-banner) center / cover no-repeat;
}

#hp-gate .hp-gate-banner::after {
  content: "";
  position: absolute;
  right: 14px;
  top: 10px;
  width: 26px;
  height: 32px;
  background: var(--hp-sparkle) center / contain no-repeat;
}

#hp-gate .hp-gate-body {
  padding: 16px 26px 18px;
  text-align: center;
}

#hp-gate .hp-gate-site {
  height: 92px;
  margin: -42px 0 0;
  position: relative;
  background: var(--hp-profile) center / contain no-repeat;
  filter: drop-shadow(0 2px 5px var(--hp-drop));
}

#hp-gate .hp-gate-sub {
  margin: 4px 0 16px;
  color: var(--hp-ink3);
  font-size: var(--hp-fs-micro);
}

#hp-gate label.hp-gate-field {
  display: block;
  margin: 0 0 4px;
  text-align: left;
  color: var(--hp-ink2);
  font: 400 var(--hp-fs-micro) / 1.4 var(--hp-font-label);
  letter-spacing: 0.12em;
}

#hp-gate input[type="text"] {
  display: block;
  width: 100%;
  box-sizing: border-box;
  height: 2.4em;
  margin: 0 0 8px;
  padding: 0 1em;
  border: 1px solid var(--hp-line);
  border-radius: 999px;
  background: var(--hp-field);
  box-shadow: inset 0 1px 2px rgba(60, 62, 72, 0.08);
  color: var(--hp-ink);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-mono);
  outline: none;
}

#hp-gate input[type="text"]:focus {
  border-color: var(--hp-ink3);
}

#hp-gate .hp-gate-remember {
  display: flex;
  align-items: center;
  gap: 0.5em;
  margin: 0 0 14px;
  color: var(--hp-ink2);
  font-size: var(--hp-fs-micro);
  cursor: pointer;
}

#hp-gate .hp-gate-enter {
  display: block;
  width: 100%;
  height: 2.6em;
  margin: 0 0 8px;
  border: 1px solid var(--hp-btn);
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.32), rgba(255, 255, 255, 0) 55%), var(--hp-btn);
  color: var(--hp-btn-ink);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-label);
  letter-spacing: 0.08em;
  cursor: pointer;
}

#hp-gate .hp-gate-enter:hover {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.32), rgba(255, 255, 255, 0) 55%), var(--hp-btn-hover);
}

#hp-gate .hp-gate-guest {
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: var(--hp-ink3);
  font: 400 var(--hp-fs-micro) / 1.6 var(--hp-font-mono);
  text-decoration: underline dotted;
  text-underline-offset: 0.25em;
  cursor: pointer;
}

#hp-gate .hp-gate-loading {
  padding: 26px 0 6px;
}

#hp-gate .hp-gate-loading p:first-child {
  margin: 0 0 12px;
  color: var(--hp-ink2);
  font: 400 var(--hp-fs-small) / 1 var(--hp-font-label);
  letter-spacing: 0.12em;
}

#hp-gate .hp-gate-bar-track {
  height: 10px;
  box-sizing: border-box;
  padding: 2px;
  border: 1px solid var(--hp-ink3);
  border-radius: 999px;
  background: var(--hp-field);
  overflow: hidden;
}

#hp-gate .hp-gate-bar-track i {
  display: block;
  width: 6%;
  height: 100%;
  border-radius: 999px;
  background: var(--hp-btn);
  transition: width 1.3s cubic-bezier(0.3, 0.6, 0.4, 1);
}

#hp-gate .hp-gate-bar-track i.is-full {
  width: 100%;
}

#hp-gate .hp-gate-loading .hp-gate-sub {
  margin: 12px 0 0;
}

#hp-gate .hp-gate-foot {
  margin: 14px 0 0;
  padding: 8px 0 0;
  border-top: 1px dashed var(--hp-line);
  color: var(--hp-ink3);
  font-size: var(--hp-fs-micro);
}
